-- MALKOM 3.0 content seed (exported from the reference database).
-- Users here are app-profile rows; they link to Supabase auth on first sign-in.
begin;
-- The score-matrix triggers would auto-create rows the dump also inserts.
alter table public."ApproachOption" disable trigger trg_option_matrix;
alter table public."Criterion" disable trigger trg_criterion_matrix;













alter table public."ApproachOption" enable trigger trg_option_matrix;
alter table public."Criterion" enable trigger trg_criterion_matrix;
commit;
