INSERT INTO public."Approach" (id, title, context, "recommendedOptionId", rationale, "order", "updatedAt") VALUES ('cms4nf976000172odoqax0p9h', 'Platform Strategy for MALKOM 3.0', 'MALKOM 3.0 must modernise the current workflow while keeping migration risk low. Three delivery options were evaluated against cost, speed and long-term fit.', 'cms4nf976000372odx9whr7rg', 'Balanced modernisation delivers fastest stakeholder value at acceptable risk.', 0, '2026-07-28 12:45:23.163');
INSERT INTO public."ApproachOption" (id, "approachId", title, description, pros, cons, effort, risk, "order") VALUES ('cms4nf976000272odolg5fr0x', 'cms4nf976000172odoqax0p9h', 'Option A — Rebuild on modern stack', 'Greenfield rebuild of the core platform with a phased cut-over.', '{"Clean architecture","No legacy constraints","Best long-term velocity"}', '{"Highest upfront cost","Longest time-to-value","Parallel-run burden"}', 5, 4, 0);
INSERT INTO public."ApproachOption" (id, "approachId", title, description, pros, cons, effort, risk, "order") VALUES ('cms4nf976000372odx9whr7rg', 'cms4nf976000172odoqax0p9h', 'Option B — Incremental modernisation', 'Strangler-pattern modernisation of highest-value modules first.', '{"Early value delivery","Contained risk per slice","Budget spread over time"}', '{"Temporary dual-stack complexity","Needs strong interface discipline"}', 3, 2, 1);
INSERT INTO public."ApproachOption" (id, "approachId", title, description, pros, cons, effort, risk, "order") VALUES ('cms4nf976000472odphii90b7', 'cms4nf976000172odoqax0p9h', 'Option C — Extend current platform', 'Keep the existing platform and extend it for MVP scope only.', '{"Lowest cost","Fastest initial delivery"}', '{"Compounds technical debt","Limits future capability","Scaling ceiling"}', 2, 3, 2);
INSERT INTO public."Consideration" (id, "approachId", "optionId", kind, text, "order") VALUES ('cms4nf976000972od8jp4jqfu', 'cms4nf976000172odoqax0p9h', NULL, 'CONSTRAINT', 'MVP must land within the current budget cycle.', 0);
INSERT INTO public."Consideration" (id, "approachId", "optionId", kind, text, "order") VALUES ('cms4nf976000a72od675iyfic', 'cms4nf976000172odoqax0p9h', NULL, 'DEPENDENCY', 'InstaSafe SSO integration is required before rollout.', 1);
INSERT INTO public."Consideration" (id, "approachId", "optionId", kind, text, "order") VALUES ('cms4nf976000b72odukr72l7i', 'cms4nf976000172odoqax0p9h', NULL, 'ASSUMPTION', 'Current data model can be migrated incrementally.', 2);
INSERT INTO public."Consideration" (id, "approachId", "optionId", kind, text, "order") VALUES ('cms4nf976000c72odo4qe9lhi', 'cms4nf976000172odoqax0p9h', NULL, 'RISK', 'Key-person dependency on legacy platform knowledge.', 3);
