INSERT INTO public."ContentBlock" (id, "sectionId", "parentId", kind, payload, "order", status, "createdById", "updatedById", "publishedAt", "createdAt", "updatedAt") VALUES ('cms4nf9ar001i72odeg2p9vl8', 'cms4nf9aj001g72oduvhcfcj6', NULL, 'RICH_TEXT', '{"markdown": "Each approach below lists its **options**, a weighted **comparison matrix**, and the **considerations** behind the recommendation. Use the feedback button to challenge anything — every option, score and consideration accepts feedback individually."}', 0, 'PUBLISHED', 'cms4ltpj50000tpqxbjl07o7n', NULL, '2026-07-28 12:45:23.283', '2026-07-28 12:45:23.283', '2026-07-28 12:45:23.283');
