INSERT INTO public."ContentBlock" (id, "sectionId", "parentId", kind, payload, "order", status, "createdById", "updatedById", "publishedAt", "createdAt", "updatedAt") VALUES ('cms4nf9bp001r72odffalphk8', 'cms4nf9bi001p72odyk6p05nj', NULL, 'PROBLEM_STATEMENT', '{"title": "Fragmented planning communication", "impact": "Decisions are re-litigated, feedback is lost, and alignment costs weeks per cycle.", "severity": 4, "narrative": "Programme plans live in slide decks and email threads. Stakeholders review stale copies, and feedback arrives through channels that cannot be tracked or actioned systematically.", "stakeholders": ["Programme leadership", "Delivery teams", "Business stakeholders"]}', 0, 'PUBLISHED', 'cms4ltpj50000tpqxbjl07o7n', NULL, '2026-07-28 12:45:23.317', '2026-07-28 12:45:23.318', '2026-07-28 12:45:23.318');
INSERT INTO public."ContentBlock" (id, "sectionId", "parentId", kind, payload, "order", status, "createdById", "updatedById", "publishedAt", "createdAt", "updatedAt") VALUES ('cms4nf9bw001t72od0shiz9ox', 'cms4nf9bi001p72odyk6p05nj', NULL, 'PROBLEM_STATEMENT', '{"title": "No single view of decision rationale", "impact": "The same questions are answered repeatedly; historical context is unrecoverable.", "severity": 3, "narrative": "Options analysis and the reasoning behind chosen approaches are scattered, making onboarding slow and challenge cycles repetitive.", "stakeholders": ["New joiners", "Architecture board", "Programme leadership"]}', 1, 'PUBLISHED', 'cms4ltpj50000tpqxbjl07o7n', NULL, '2026-07-28 12:45:23.324', '2026-07-28 12:45:23.324', '2026-07-28 12:45:23.324');
